from base_sensor import BaseVirtualSensor

class INA3221_Simulator(BaseVirtualSensor):
    REGISTERS = {
        0x00: {"name": "CONFIG", "reset": 0x7127},
        0x01: {"name": "SHUNT1", "reset": 0x0000},
        0x02: {"name": "VBUS1", "reset": 0x0000},
        0x03: {"name": "SHUNT2", "reset": 0x0000},
        0x04: {"name": "VBUS2", "reset": 0x0000},
        0x05: {"name": "SHUNT3", "reset": 0x0000},
        0x06: {"name": "VBUS3", "reset": 0x0000},
        0x07: {"name": "CRIT1", "reset": 0x7FF8},
        0x08: {"name": "WARN1", "reset": 0x7FF8},
        0x09: {"name": "CRIT2", "reset": 0x7FF8},
        0x0A: {"name": "WARN2", "reset": 0x7FF8},
        0x0B: {"name": "CRIT3", "reset": 0x7FF8},
        0x0C: {"name": "WARN3", "reset": 0x7FF8},
        0x0D: {"name": "SHUNT_SUM", "reset": 0x0000},
        0x0E: {"name": "SHUNT_SUM_LIMIT", "reset": 0x7FFE},
        0x0F: {"name": "MASK_ENABLE", "reset": 0x0002},
        0x10: {"name": "PV_UPPER", "reset": 0x2710},
        0x11: {"name": "PV_LOWER", "reset": 0x2328},
        0xFE: {"name": "MANUF_ID", "reset": 0x5449},
        0xFF: {"name": "DIE_ID", "reset": 0x3220},
    }

    READ_ONLY_REGISTERS = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x0D, 0xFE, 0xFF}

    def __init__(self):
        super().__init__()
        for addr, info in self.REGISTERS.items():
            self.regs[addr] = info["reset"]

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]

        if nbytes == 1:
            return (value >> 8) & 0xFF

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr in self.READ_ONLY_REGISTERS:
            return

        if nbytes == 1:
            mask = 0xFF00 if addr == 0x00 else 0xFFFF
            self.regs[addr] = (self.regs[addr] & mask) | ((data << 8) & 0xFF00)
        else:
            self.regs[addr] = data
